// Tests for the MV7+ packet layer.
//
// The golden frames in go-vectors.txt were generated by the Go reference
// implementation of the same protocol (the community mv7-linux-support
// project), so a passing run means this JavaScript port emits byte-identical
// packets, not merely self-consistent ones.
//
// Run: node --test test/
const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');

const core = require('../mv7-core.js');

const toHex = (bytes) => Buffer.from(bytes).toString('hex');

function loadVectors() {
  const file = path.join(__dirname, 'go-vectors.txt');
  const vectors = {};
  for (const line of fs.readFileSync(file, 'utf8').trim().split('\n')) {
    const [name, hex] = line.trim().split(/\s+/);
    vectors[name] = hex;
  }
  return vectors;
}

test('CRC-16/ANSI check value', () => {
  const data = Buffer.from('123456789', 'ascii');
  assert.strictEqual(core.crc16ANSI(data), 0xbb3d);
});

test('frames match the Go reference implementation byte for byte', () => {
  const v = loadVectors();
  const built = {
    getGainHdr3: core.getPacket(0x11, 0x00, core.FEAT.GAIN),
    getPlaybackMix: core.getPacket(0x12, 0x03, core.FEAT.MIX),
    setGain2450: core.setPacket(0x13, 0x00, core.FEAT.GAIN, [0x09, 0x92]),
    setMuteOn: core.setPacket(0x14, 0x00, core.FEAT.MUTE, [1]),
    setToneNeg40: core.setPacket(0x15, 0x00, core.FEAT.TONE, [0xff, 0xd8]),
    getLockLedBehavior: core.getLockPacket(0x16, 0x0c, 0xa4),
    setLockLedColor: core.setLockPacket(0x17, 0x0c, 0xa2, [0x00, 0x12, 0x34, 0x56]),
    confirm: core.confirmPacket(0x18),
    setMicMix60: core.setPacket(0x19, 0x00, core.FEAT.MIX, [60]),
    setDeviceName: core.setLockPacket(0x1a, 0x00, 0x12, core.encodeLPString('MIC')),
    setLedBrightness: core.setLockPacket(0x1b, 0x0c, 0x42, [5]),
    getDeviceName: core.getLockPacket(0x1c, 0x00, 0x12),
  };
  for (const [name, packet] of Object.entries(built)) {
    assert.strictEqual(packet.length, 64, name + ' length');
    assert.strictEqual(packet[0], 1, name + ' report id');
    assert.strictEqual(toHex(packet), v[name], name + ' bytes');
  }
});

test('parse rejects a corrupted CRC', () => {
  const packet = core.getPacket(0x01, 0x00, core.FEAT.GAIN);
  packet[20] ^= 0xff;
  assert.strictEqual(core.parsePacket(packet), null);
});

test('demo transport round-trips every setting', async () => {
  const transport = new core.DemoTransport(core.defaultState());
  const client = new core.Client(transport);
  const before = await client.readState();
  assert.strictEqual(before.gain, 0);
  assert.strictEqual(before.muted, false);

  await client.setGain(21.5);
  await client.setMuted(true);
  await client.setHPF(2);
  await client.setCompressor(2);
  await client.setTone(-40);
  await client.setMicMix(60);
  await client.setPlaybackMix(35);
  await client.setLEDColor('solid', [0x11, 0x22, 0x33]);
  await client.setLEDBrightness(6);
  await client.setReverbType(1);
  await client.setReverbIntensity(80);
  await client.renameDevice('DESK MIC');

  const after = await client.readState();
  assert.strictEqual(after.gain, 21.5);
  assert.strictEqual(after.muted, true);
  assert.strictEqual(after.hpf, 2);
  assert.strictEqual(after.compressor, 2);
  assert.strictEqual(after.tone, -40);
  assert.strictEqual(after.micMix, 60);
  assert.strictEqual(after.playbackMix, 35);
  assert.deepStrictEqual(after.ledSolidColor, [0x11, 0x22, 0x33]);
  assert.strictEqual(after.ledBrightness, 6);
  assert.strictEqual(after.reverbType, 1);
  assert.strictEqual(after.reverbIntensity, 80);
  assert.strictEqual(after.deviceName, 'DESK MIC');
  assert.ok(after.answered >= 20, 'readback answered ' + after.answered + ' settings');
});

test('gain is clamped and encoded in hundredths', async () => {
  const transport = new core.DemoTransport(core.defaultState());
  const client = new core.Client(transport);
  await client.setGain(99);
  const state = await client.readState();
  assert.strictEqual(state.gain, 36);
});

test('tone snaps to ten-percent steps', async () => {
  const transport = new core.DemoTransport(core.defaultState());
  const client = new core.Client(transport);
  await client.setTone(-44);
  const state = await client.readState();
  assert.strictEqual(state.tone, -40);
});
